import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

totals = {}

for r in range(2, vws.max_row + 1):
    product = vws.cell(row=r, column=1).value
    quantity = vws.cell(row=r, column=2).value

    if product is None:
        continue

    product_str = str(product).strip()
    if not product_str:
        continue

    letter = product_str[0].upper()

    if isinstance(quantity, bool):
        continue

    try:
        qty = float(quantity)
    except (TypeError, ValueError):
        continue

    totals[letter] = totals.get(letter, 0.0) + qty

letters = []
for c in range(4, 8):
    header = vws.cell(row=2, column=c).value
    if header is not None and str(header).strip():
        letters.append(str(header).strip().upper()[0])
    else:
        letters.append(chr(ord("A") + c - 4))

for c, letter in zip(range(4, 8), letters):
    value = totals.get(letter, 0.0)
    if float(value).is_integer():
        value = int(value)
    ws.cell(row=3, column=c).value = value

print("Totals:", totals)
print("Letters:", letters)

wb.save(OUT)
